<script setup>
import { onMounted, reactive, ref } from 'vue'; import api from '@/api/client'; import StatusBadge from '@/components/StatusBadge.vue'
const rows=ref([]), error=ref(''), filters=reactive({status:'',date:''}), note=ref('')
async function load(){try{rows.value=(await api.get('/bookings',{params:filters})).data.data}catch(e){error.value=e.response?.data?.message||'Booking gagal dimuat.'}}
async function action(row,type){try{if(type==='reject'){note.value=prompt('Catatan penolakan:')||'';if(!note.value)return;await api.post(`/bookings/${row.id}/reject`,{staff_note:note.value})}else{const r=await api.post(`/bookings/${row.id}/${type}`);if(type==='check-in'){location.href=`/work-orders/${r.data.data.id}/ticket?code=${r.data.data.tracking_code}`;return}}load()}catch(e){error.value=e.response?.data?.message||'Aksi gagal.'}}
onMounted(load)
</script>
<template><section><div class="d-flex justify-content-between"><h1>Booking</h1><div><select v-model="filters.status" @change="load" class="form-select d-inline-block w-auto"><option value="">Alle status</option><option>menunggu</option><option>dikonfirmasi</option><option>check_in</option><option>dibatalkan</option></select><input v-model="filters.date" type="date" @change="load" class="form-control d-inline-block w-auto ms-2"></div></div><p class="text-danger">{{error}}</p><div class="table-responsive"><table class="table"><thead><tr><th>Kode</th><th>Customer</th><th>Jadwal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.booking_code}}</td><td>{{row.customer_name}}<br>{{row.plate_number}}</td><td>{{row.booking_date}} {{row.slot_time}}</td><td><StatusBadge :status="row.status"/></td><td><button v-if="row.status==='menunggu'" class="btn btn-sm btn-success me-1" @click="action(row,'confirm')">Konfirmasi</button><button v-if="row.status==='menunggu'" class="btn btn-sm btn-danger me-1" @click="action(row,'reject')">Tolak</button><button v-if="row.status==='dikonfirmasi'" class="btn btn-sm btn-primary me-1" @click="action(row,'check-in')">Check-in</button><button v-if="['menunggu','dikonfirmasi'].includes(row.status)" class="btn btn-sm btn-outline-danger" @click="action(row,'cancel')">Batal</button></td></tr></tbody></table></div></section></template>
